"""Deterministic front130 sampling of the actual rectangular source-anchor stack."""
import argparse,pathlib,json,hashlib,math
import cv2,numpy as np
p=argparse.ArgumentParser();p.add_argument('--root',required=True);p.add_argument('--out',required=True);a=p.parse_args();root=pathlib.Path(a.root);out=pathlib.Path(a.out);out.mkdir(parents=True,exist_ok=True);selection=root/'stops/stop-04/selected.json';s=json.loads(selection.read_text());cam=s['camera'];bp=root/s['panorama'];sp=root/'stops/stop-04/source.png';base=cv2.imread(str(bp));source=cv2.imread(str(sp));n=1400;yy,xx=np.mgrid[:n,:n];t=math.tan(math.radians(65));q=np.stack([(2*(xx+.5)/n-1)*t,np.ones((n,n)),(1-2*(yy+.5)/n)*t],axis=-1);q/=np.linalg.norm(q,axis=-1,keepdims=True)
mx=((np.arctan2(q[...,0],q[...,1])/(2*np.pi)+.5)*base.shape[1]-.5).astype('float32');my=((.5-np.arcsin(q[...,2])/np.pi)*base.shape[0]-.5).astype('float32');bg=cv2.remap(base,mx,my,cv2.INTER_LINEAR,borderMode=cv2.BORDER_WRAP)
y,p=cam['yaw'],cam['pitch'];f=np.array([math.sin(y)*math.cos(p),math.cos(y)*math.cos(p),math.sin(p)]);r=np.array([math.cos(y),-math.sin(y),0]);u=np.array([-math.sin(y)*math.sin(p),-math.cos(y)*math.sin(p),math.cos(p)]);z=q@f;st=math.tan(math.radians(cam['fov']/2));sx=(q@r)/np.maximum(z,1e-8)/(st*16/9);sy=(q@u)/np.maximum(z,1e-8)/st;edge=np.maximum(abs(sx),abs(sy));blend=np.clip((edge-.94)/.06,0,1);weight=(1-blend*blend*(3-2*blend))*(z>0);fg=cv2.remap(source,((sx+1)*source.shape[1]/2-.5).astype('float32'),((1-sy)*source.shape[0]/2-.5).astype('float32'),cv2.INTER_LINEAR,borderMode=cv2.BORDER_REPLICATE);result=np.rint(bg*(1-weight[...,None])+fg*weight[...,None]).astype('uint8');cv2.imwrite(str(out/'front-input.png'),result)
sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest();rec={'schemaVersion':1,'operation':'Existing panorama plus rectangular source texture sampled by perspective rays; no artistic changes','inputs':{'base':{'path':s['panorama'],'sha256':sha(bp)},'source':{'path':'stops/stop-04/source.png','sha256':sha(sp)},'selectionSha256':sha(selection)},'sourceCamera':dict(cam,aspect=16/9,featherStart=.94),'outputCamera':{'yaw':0,'pitch':0,'fov':130,'aspect':1},'output':{'path':'front-input.png','width':n,'height':n,'sha256':sha(out/'front-input.png')},'sampling':'OpenCV bilinear encoded RGB; same projection and feather equations as runtime source anchor; no claim CPU/WebGL bit identity','scriptSha256':sha(__file__)};(out/'front-input.json').write_text(json.dumps(rec,indent=2)+'\n');print(json.dumps(rec))
